const test = require('node:test');
const assert = require('node:assert/strict');
const { pageBins } = require('../bins.cjs');
test('offset and count are separate', () => {
  const bins = Object.freeze(['A1','A2','B1','B2','C1']);
  assert.deepEqual(pageBins(bins, 2, 2), ['B1','B2']);
  assert.deepEqual(pageBins(bins, 1, 3), ['A2','B1','B2']);
  assert.deepEqual(pageBins(bins, 4, 8), ['C1']);
  assert.deepEqual(pageBins(bins, 8, 2), []);
  assert.deepEqual(pageBins(bins, 2, 0), []);
  assert.deepEqual(pageBins([], 0, 2), []);
  const all = pageBins(bins, 0, 5);
  assert.deepEqual(all, bins);
  assert.notStrictEqual(all, bins);
});

